/// </summary>
[ExtensionOf(classStr(SalesPackingSlipDP))]
final public class AVASalesPackingSlipDPCls_Extension
{
}

Method.Source:
/// <summary>
/// Initializes a sales packing slip header.
/// </summary>
/// <returns>
/// The initialized <c>SalesPackingSlipHeaderTmp</c> sales packing slip header record.
/// </returns>
protected SalesPackingSlipHeaderTmp initializeSalesPackingSlipHeader()
{
    SalesPackingSlipHeaderTmp   salesPackingSlipHeaderTmp   = next initializeSalesPackingSlipHeader();
    HcmWorker                   avaDlvResponsible           = HcmWorker::find(this.parmCustPackingSlipJour().AVADlvResponsible);
    SalesTable                  avaSalesTable               = this.parmCustPackingSlipJour().salesTable();
    PurchTable                  avaPurchTable_IC            = avaSalesTable.referencePurchTable();
    SalesTable                  avaSalesTable_IC            = avaPurchTable_IC.intercompanySalesTable();

    salesPackingSlipHeaderTmp.AVASalesGroup                 = this.parmCustPackingSlipJour().AVASalesGroup;   
    salesPackingSlipHeaderTmp.AVAVATNum                     = this.parmCustPackingSlipJour().AVAVATNum;
    salesPackingSlipHeaderTmp.AVAShipCarrierDeliveryContact = this.parmCustPackingSlipJour().AVAShipCarrierDeliveryContact;
    salesPackingSlipHeaderTmp.AVAShipCarrierDeliveryMobile  = this.parmCustPackingSlipJour().AVAShipCarrierDeliveryMobile;
    salesPackingSlipHeaderTmp.NDX_ShipCarrierDeliveryFax    = this.parmCustPackingSlipJour().NDX_ShipCarrierDeliveryFax;
    salesPackingSlipHeaderTmp.NDX_ShipCarrierDeliveryPhone  = this.parmCustPackingSlipJour().NDX_ShipCarrierDeliveryPhone;
    salesPackingSlipHeaderTmp.AVARicoCustomer               = this.parmCustPackingSlipJour().AVARicoCustomer;

    if(this.parmCustPackingSlipJour().PrintMgmtSiteId != '')
    {
        salesPackingSlipHeaderTmp.AVAInventSiteId               = this.parmCustPackingSlipJour().PrintMgmtSiteId;
    }
    else
    {
        salesPackingSlipHeaderTmp.AVAInventSiteId               = this.parmCustPackingSlipJour().AVAInventSiteId;
    }

    if(this.parmCustPackingSlipJour().CustomerRef != '')
    {
        salesPackingSlipHeaderTmp.AVAPurchaseOrder = strFmt("@NDX:NXAVar1FromVar2CommaVar3", this.parmCustPackingSlipJour().PurchaseOrder, this.parmCustPackingSlipJour().KCS_PurchRefDate, this.parmCustPackingSlipJour().CustomerRef);
    }
    else
    {
        salesPackingSlipHeaderTmp.AVAPurchaseOrder = strFmt("@NDX:NXAVar1FromVar2", this.parmCustPackingSlipJour().PurchaseOrder, this.parmCustPackingSlipJour().KCS_PurchRefDate);
    }

    if(avaSalesTable_IC)
    {
        changecompany(avaSalesTable_IC.InterCompanyCompanyId)
        {
            HcmWorker   avaDlvResponsibleLoc    = HcmWorker::find(avaSalesTable_IC.AVADlvResponsible);

            salesPackingSlipHeaderTmp.AVADlvResponsibleMail     = avaDlvResponsibleLoc.email();
            salesPackingSlipHeaderTmp.AVADlvResponsibleName     = avaDlvResponsibleLoc.avaPersonName();
            salesPackingSlipHeaderTmp.AVADlvResponsiblePhone    = avaDlvResponsibleLoc.phone() + " " + avaDlvResponsibleLoc.phoneLocal();
        }
    }
    else
    {
        salesPackingSlipHeaderTmp.AVADlvResponsibleMail     = avaDlvResponsible.email();
        salesPackingSlipHeaderTmp.AVADlvResponsibleName     = avaDlvResponsible.avaPersonName();
        salesPackingSlipHeaderTmp.AVADlvResponsiblePhone    = avaDlvResponsible.phone() + " " + avaDlvResponsible.phoneLocal();
    }

    return salesPackingSlipHeaderTmp;
}

/// <summary>
/// Initializes a sales packing slip line.
/// </summary>
/// <param name = "_salesPackingSlipHeaderTmp">
/// A <c>SalesPackingSlipHeaderTmp</c> record which is the sales packing slip header.
/// </param>
/// <param name = "_packingSlipLineSelection">
/// A <c>SalesPackingSlipDPPackingSlipLineQuerySelection</c> object which the sales packing slip line should be initialized from.
/// </param>
/// <returns>
/// The initialized <c>SalesPackingSlipDetailsTmp</c> sales packing slip line record.
/// </returns>
protected SalesPackingSlipDetailsTmp initializeSalesPackingSlipLine(
    SalesPackingSlipHeaderTmp                       _salesPackingSlipHeaderTmp,
    SalesPackingSlipDPPackingSlipLineQuerySelection _packingSlipLineSelection)
{
    SalesPackingSlipDetailsTmp salesPackingSlipTmp = next initializeSalesPackingSlipLine(_salesPackingSlipHeaderTmp, _packingSlipLineSelection);

    if(this.parmCustPackingSlipJour().DlvReason
        || this.parmCustPackingSlipJour().postalAddress().CountryRegionId != CompanyInfo::find().postalAddress().CountryRegionId)
    {
        salesPackingSlipTmp.AVAOrigCountryName      = _packingSlipLineSelection.parmCustPackingSlipTrans().OrigCountryRegionId;
        salesPackingSlipTmp.AVAIntrastatCommodity   = EcoResCategory::find(_packingSlipLineSelection.parmCustPackingSlipTrans().AVAIntrastatCommodity).Code;
    }

    salesPackingSlipTmp.AVALineNum              = _packingSlipLineSelection.parmCustPackingSlipTrans().LineNum;
    salesPackingSlipTmp.AVALineNetWeight        = _packingSlipLineSelection.parmCustPackingSlipTrans().inventTable().NetWeight * _packingSlipLineSelection.parmCustPackingSlipTrans().Qty;
    salesPackingSlipTmp.AVAInventColorId        = _packingSlipLineSelection.parmCustPackingSlipTransInventDim().InventColorId;

    return salesPackingSlipTmp;
}
